<?php
require_once __DIR__.'/../../includes/comercial.php';exigir_comercial_admin();$db=obtener_conexion();$tipo=(string)($_GET['tipo']??'');if(!in_array($tipo,['ventas','cobros'],true)){http_response_code(400);exit('Tipo de exportacion invalido.');}$nombre=$tipo.'_'.date('Ymd_His').'.csv';header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.$nombre.'"');$salida=fopen('php://output','w');fputcsv($salida,$tipo==='ventas'?['ID','Fecha','Cliente','Instrumento','Total']:['ID','Fecha','Reparacion','Instrumento','Monto']);if($tipo==='ventas'){$s=$db->query('SELECT v.id_venta,v.fecha,c.nombre,i.codigo_qr,v.total FROM venta v INNER JOIN cliente c ON c.id_cliente=v.id_cliente LEFT JOIN instrumento i ON i.id_instrumento=v.id_instrumento ORDER BY v.fecha DESC');while($r=$s->fetch())fputcsv($salida,$r);}else{$s=$db->query('SELECT c.id_cobro,c.fecha,c.id_reparacion,i.codigo_qr,c.monto FROM cobro c INNER JOIN reparacion r ON r.id_reparacion=c.id_reparacion INNER JOIN instrumento i ON i.id_instrumento=r.id_instrumento ORDER BY c.fecha DESC');while($r=$s->fetch())fputcsv($salida,$r);}fclose($salida);registrar_bitacora('reporte_exportado',$tipo);exit;
